// Selects rows that still need qualifying and normalizes their website URL.
// Pending = status is empty, "pending" or "retry". Rows are capped at max_rows_per_run.
const config = $('Config').first().json;
const limit = Number(config.max_rows_per_run) > 0 ? Number(config.max_rows_per_run) : 25;
const PENDING_STATUSES = new Set(['', 'pending', 'retry']);

function normalizeUrl(raw) {
  let candidate = String(raw).trim().replace(/\s+/g, '');
  if (!/^https?:\/\//i.test(candidate)) candidate = 'https://' + candidate;
  // The URL class is not available in the Code node sandbox, so parse with a regex:
  // lowercase scheme and host, drop query, fragment and trailing slashes.
  const match = candidate.match(/^(https?):\/\/([^\/?#]+)([^?#]*)/i);
  if (!match) {
    // Unparseable input is passed through as-is: the fetch step will fail
    // and the row ends up with status=error and a readable message.
    return candidate;
  }
  const path = match[3].replace(/\/+$/, '');
  return `${match[1].toLowerCase()}://${match[2].toLowerCase()}${path}`;
}

const seen = new Set();
const selected = [];

for (const item of $input.all()) {
  const row = item.json;
  const status = String(row.status ?? '').trim().toLowerCase();
  const website = String(row.website ?? '').trim();
  if (!PENDING_STATUSES.has(status) || !website) continue;

  const url = normalizeUrl(website);
  if (seen.has(url.toLowerCase())) continue; // duplicate website in the sheet
  seen.add(url.toLowerCase());

  selected.push({
    json: {
      company_name: String(row.company_name ?? '').trim(),
      website, // original value, used as the key when updating the row
      url,
    },
  });
  if (selected.length >= limit) break;
}

return selected;

// Cleans the Jina Reader markdown, trims it to a character budget and
// flags pages that are empty or blocked so they never reach the LLM.
const config = $('Config').first().json;
const row = $('Loop Over Companies').item.json;
const maxChars = Number(config.max_markdown_chars) > 0 ? Number(config.max_markdown_chars) : 12000;
const minChars = Number(config.min_markdown_chars) >= 0 ? Number(config.min_markdown_chars) : 300;

// Phrases typical of bot walls and error pages. Only checked on short pages
// so a long, legitimate page that mentions "captcha" is not rejected.
const BLOCKED_PATTERNS = [
  /captcha/i,
  /access denied/i,
  /attention required/i,
  /just a moment\.\.\./i,
  /enable javascript and cookies/i,
  /target url returned error \d{3}/i,
  /\b(403 forbidden|404 not found|502 bad gateway|503 service unavailable)\b/i,
  /this domain (is|may be) for sale/i,
];
const BLOCK_CHECK_MAX_LENGTH = 3000;

const raw = typeof $json.data === 'string' ? $json.data : '';

let markdown = raw
  .replace(/!\[[^\]]*\]\([^)]*\)/g, '')      // drop images
  .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')    // keep link text, drop URLs
  .replace(/[{}]/g, '')                      // braces are template variables in LLM prompts
  .replace(/[ \t]+/g, ' ')
  .replace(/ *\n */g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const originalChars = markdown.length;
let truncated = false;
if (markdown.length > maxChars) {
  const cut = markdown.slice(0, maxChars);
  const lastBreak = cut.lastIndexOf('\n');
  // Prefer to cut at a line break when one is reasonably close to the limit.
  markdown = (lastBreak > maxChars * 0.8 ? cut.slice(0, lastBreak) : cut).trim();
  truncated = true;
}

let skipReason = '';
if (!markdown) {
  skipReason = 'Empty page content';
} else if (originalChars < BLOCK_CHECK_MAX_LENGTH && BLOCKED_PATTERNS.some((p) => p.test(markdown))) {
  skipReason = 'Website blocked the reader or returned an error page';
} else if (markdown.length < minChars) {
  skipReason = `Too little readable content (${markdown.length} chars, minimum ${minChars})`;
}

return {
  json: {
    company_name: row.company_name,
    website: row.website,
    url: row.url,
    markdown,
    original_chars: originalChars,
    truncated,
    content_ok: skipReason === '',
    skip_reason: skipReason,
  },
};

