// Treats the LLM output as untrusted input: clamps the score, normalizes
// enums and caps text lengths. Throws only when the output is unusable,
// which routes the item to the error branch.
const source = $('Prepare Page Content').item.json;
const result = $json.output;

if (!result || typeof result !== 'object') {
  throw new Error('LLM returned no structured output');
}

const SIZE_BUCKETS = ['1-10', '11-50', '51-200', '201-500', '501-1000', '1000+', 'unknown'];
const clean = (value, maxLength) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, maxLength);

const rawScore = Number(result.score);
if (!Number.isFinite(rawScore)) {
  throw new Error(`LLM output has no numeric score (got: ${clean(result.score, 40) || 'empty'})`);
}
const score = Math.min(10, Math.max(1, Math.round(rawScore)));

const reasonList = Array.isArray(result.reasons) ? result.reasons : [result.reasons];
const reasons = reasonList.map((r) => clean(r, 200)).filter(Boolean).slice(0, 5);

const size = clean(result.company_size_guess, 20);

return {
  json: {
    company_name: source.company_name,
    website: source.website,
    score,
    industry: clean(result.industry, 80) || 'Unknown',
    company_size_guess: SIZE_BUCKETS.includes(size) ? size : 'unknown',
    reasons: reasons.join(' | '),
    pitch: clean(result.pitch, 700),
    qualified_at: new Date().toISOString(),
  },
};

// Collects failures from every step (fetch, empty page, LLM, validation,
// sheet append) into one row shape so the loop can continue.
let row = {};
try {
  row = $('Loop Over Companies').item.json;
} catch (error) {
  row = {}; // paired item not resolvable; fall back to fields on the item itself
}

const err = $json.error;
const errorText = typeof err === 'string' ? err : (err && (err.message || err.description)) || '';
const message = $json.skip_reason || errorText || $json.message || 'Unknown error';

return {
  json: {
    company_name: row.company_name ?? $json.company_name ?? '',
    website: row.website ?? $json.website ?? '',
    status: 'error',
    error_message: String(message).replace(/\s+/g, ' ').trim().slice(0, 300),
    processed_at: new Date().toISOString(),
  },
};

// Counts the outcome of this run from the re-read sheet. Reading the sheet
// (instead of node outputs) counts every loop iteration, not just the last one.
const config = $('Config').first().json;
const runStartedAt = Date.parse(config.run_started_at) || 0;
const threshold = Number(config.high_fit_threshold) || 7;

const counts = { done: 0, error: 0, pending: 0, high_fit: 0 };
const errors = [];

for (const { json: row } of $input.all()) {
  const status = String(row.status ?? '').trim().toLowerCase();
  if (status === '' || status === 'pending' || status === 'retry') {
    counts.pending += 1;
    continue;
  }
  const processedAt = Date.parse(row.processed_at);
  if (!Number.isFinite(processedAt) || processedAt < runStartedAt) continue; // earlier run

  if (status === 'done') {
    counts.done += 1;
    if (Number(row.score) >= threshold) counts.high_fit += 1;
  } else if (status === 'error') {
    counts.error += 1;
    errors.push(`${row.website}: ${row.error_message}`);
  }
}

const lines = [
  'AI Company Qualifier run finished.',
  `Qualified: ${counts.done} (score >= ${threshold}: ${counts.high_fit})`,
  `Errors: ${counts.error}`,
  `Still pending: ${counts.pending}`,
];
if (errors.length) lines.push('', 'First errors:', ...errors.slice(0, 5).map((e) => `- ${e}`));

return [{
  json: {
    run_started_at: config.run_started_at,
    processed: counts.done + counts.error,
    ...counts,
    errors: errors.slice(0, 10),
    summary_text: lines.join('\n'),
  },
}];
